<?php
if(!isset($admin)||!$admin['is_admin']){http_response_code(403);exit;}
$permissions=$db->query('SELECT p.user_id,p.product_id,p.can_review,u.name,u.email,c.data FROM product_purchases p JOIN users u ON u.id=p.user_id JOIN products c ON c.id=p.product_id ORDER BY p.confirmed_at DESC LIMIT 100')->fetchAll();
$feedback=$db->query('SELECT r.*,u.name,u.email FROM product_reviews r JOIN users u ON u.id=r.user_id ORDER BY r.updated_at DESC LIMIT 50')->fetchAll();
?>
<section id="reviews"><h2>Avaliações e liberação de feedback</h2><p>Somente a conta que tem um pedido concluído com o produto pode receber a liberação. Primeiro confirme a conclusão em Vendas e pedidos; depois libere o feedback abaixo.</p>
<form method="post"><?php token()?><input type="hidden" name="action" value="review_permission"><input type="hidden" name="allowed" value="1"><div class="grid"><label>E-mail usado no login do cliente<input type="email" name="email" required autocomplete="off" placeholder="cliente@exemplo.com" list="review-customers"><datalist id="review-customers"><?php foreach($customers as $customer):?><option value="<?=h($customer['email'])?>"><?=h($customer['name'])?></option><?php endforeach?></datalist></label><label>Produto comprado<select name="product_id" required><option value="">Selecione o produto</option><?php foreach($products as $row):$p=json_decode($row['data'],true);?><option value="<?=(int)$row['id']?>"><?=h($p['name'])?></option><?php endforeach?></select></label></div><button>Liberar feedback desta conta</button></form>
<h3>Contas com liberação registrada</h3><p>Uma avaliação por conta e produto. O cliente pode editar seu próprio feedback enquanto a permissão estiver liberada. Bloquear novos envios preserva o feedback já publicado.</p><div class="table-wrap"><table><thead><tr><th>Cliente / login</th><th>Produto</th><th>Permissão</th><th>Ação</th></tr></thead><tbody><?php foreach($permissions as $permission):$p=json_decode($permission['data'],true);?><tr><td><?=h($permission['name'])?><small><?=h($permission['email'])?></small></td><td><?=h($p['name'])?></td><td><?=$permission['can_review']?'Liberada':'Bloqueada'?></td><td><form method="post"><?php token()?><input type="hidden" name="action" value="review_permission"><input type="hidden" name="email" value="<?=h($permission['email'])?>"><input type="hidden" name="product_id" value="<?=(int)$permission['product_id']?>"><input type="hidden" name="allowed" value="<?=$permission['can_review']?'0':'1'?>"><button><?=$permission['can_review']?'Bloquear novos envios':'Liberar novamente'?></button></form></td></tr><?php endforeach?></tbody></table></div>
<h3>Feedbacks recentes</h3><?php if(!$feedback):?><p>Ainda não há avaliações publicadas.</p><?php endif?><?php foreach($feedback as $review):?><article class="admin-review"><strong><?=h($review['name'])?> · <?=(int)$review['rating']?>/5</strong><p><?=h($review['email'])?> · Produto #<?=(int)$review['product_id']?> · <?=h($review['updated_at'])?></p><p><?=nl2br(h($review['comment']))?></p></article><?php endforeach?></section>
